Snapshot snapshot(String sessionId);
List<DurableEvent> replay(String sessionId, long afterEventSeq);

record Reservation(long acceptedSeq, String resultRef, Status status) {}
record Commit(long acceptedSeq, long eventSeq, long snapshotRevision, String resultRef) {}
record CommandRecord(long acceptedSeq, String resultRef, Status status, Optional<Commit> commit) {
    public CommandRecord { commit = commit == null ? Optional.empty() : commit; }
}
enum Status { RESERVED, RETRYABLE, COMPLETED }
record DurableEvent(long eventSeq, long snapshotRevision, String eventType, byte[] payload) {
    public DurableEvent { payload = payload.clone(); }
    @Override public byte[] payload() { return payload.clone(); }
